import { DataTable } from '@vulcan-ai/vulcan-ui/lib/components/DataTable';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React from 'react';
import { FormattedMessage } from 'react-intl';
import { CabinetContributor } from 'src/apps/common/__generated__/types';
import { HeaderCell } from '../IAATable/IAATableCommon';
import { MemberCell } from '../IAATable/MemberCell';
import { ValueCell } from '../IAATable/ValueCell';

interface Props {
  memberIds: (string | null)[];
  memberRecord: Record<string, string>;
  indexedRecord: Record<string, number>;
  contributorMap?: Map<string, CabinetContributor>;
  labelingAgentMemberIds: Set<string | null>;
}

export function IAASummaryContent({
  memberIds,
  memberRecord,
  indexedRecord,
  contributorMap,
  labelingAgentMemberIds,
}: Props) {
  return (
    <>
      <DataTable.Head>
        <DataTable.Head.Row />
        <DataTable.Head.Row>
          <HeaderCell stickyTop stickyLeft width={175}>
            <b>
              <FormattedMessage id="common.member" />
            </b>
          </HeaderCell>
          {memberIds.map((memberId) => (
            <MemberCell
              key={memberId}
              variant="header"
              memberId={memberId}
              memberRecord={memberRecord}
              stickyTop
              contributorMap={contributorMap}
              isLabelingAgent={labelingAgentMemberIds.has(memberId)}
            />
          ))}
        </DataTable.Head.Row>
      </DataTable.Head>

      <Row>
        <MemberCell variant="body" memberId={null} memberRecord={memberRecord} contributorMap={contributorMap} />
        {memberIds.map((verticalMemberId) => {
          const key2 = [':', verticalMemberId].join('-');
          return <ValueCell key={verticalMemberId} value={indexedRecord[key2]} />;
        })}
      </Row>
    </>
  );
}

const Row = styled(DataTable.Body.Row, { name: 'IAASummaryContent-Row' })(({ theme }) => ({
  borderBottom: `1px solid ${theme.palette.lightGrey2}`,
}));

