import { useWatchValue } from '@vulcan-ai/vulcan-ui/lib/components/Form/helpers/useWatchValue';
import React from 'react';
import { projectKindToAnalyticsLabelType } from '../context/AnalyticFilter';
import { AnalyticChartWidget, AnalyticChartWidgetProps } from './AnalyticChartWidget';

export type AnalyticChartWidgetWrapperProps = Omit<AnalyticChartWidgetProps, 'projectKind' | 'dateRange'>;
type Props = AnalyticChartWidgetWrapperProps;

export function AnalyticChartWidgetWrapper(props: Props) {
  const projectKind = useWatchValue('projectKind', 'field-level', []);
  const labelType = projectKind ? projectKindToAnalyticsLabelType(projectKind) : undefined;

  const dateRange = useWatchValue('dateRange', 'field-level', []);
  const tagNames = useWatchValue('tagNames', 'field-level', []);

  return <AnalyticChartWidget {...props} labelType={labelType} dateRange={dateRange} tagNames={tagNames} />;
}

