import React from 'react';
import { EmptyAnalyticsDataMessage } from './EmptyAnalyticsDataMessage';

interface Props {
  chartId?: string;
  hasTagFilter?: boolean;
}

function getDescriptionId(chartId: string | undefined, hasTagFilter: boolean): string {
  if (chartId === 'CONFLICT_RESOLUTION_PER_PROJECT') {
    return 'analytic.conflict-resolution.no-data-available.description';
  }
  if (!hasTagFilter) {
    return 'analytic.no-data-available.no-tag-filter.description';
  }
  return 'analytic.no-data-available.description';
}

export function EmptyAnalyticsData({ chartId, hasTagFilter = false }: Props) {
  const descriptionId = getDescriptionId(chartId, hasTagFilter);

  return <EmptyAnalyticsDataMessage titleId="analytic.no-data-available.title" descriptionId={descriptionId} />;
}

