import { useConfig } from '@vulcan-ai/frontend-shared/lib/src/commons/config';
import { useActiveTeam } from '@vulcan-ai/frontend-shared/lib/src/modules/Team/hooks/useActiveTeam';
import { Box } from '@vulcan-ai/vulcan-ui/lib/components/Box/Box';
import { Grid } from '@vulcan-ai/vulcan-ui/lib/components/Grid';
import React, { FC } from 'react';
import { ChartLevel, ChartSet } from 'src/apps/common/__generated__/types';
import { AnalyticChartsGrid } from 'src/modules/Analytic/components/AnalyticChartsGrid';
import { useGetChartsQuery } from 'src/modules/Analytic/hooks/useGetChartsQuery';
import { AnalyticTagDropdownField } from '../AnalyticFilterWidget/AnalyticTagFilterWidget';
import { AnalyticTrendsDateFilter } from '../AnalyticTrendsDateFilter';
import { OverallProjectsChart } from './OverallProjectsChart';
import { RemainingFilesChart } from './RemainingFilesChart';

export const TeamOverviewWidget: FC = () => {
  const config = useConfig();
  const { id: teamId } = useActiveTeam();
  const getChartsQuery = useGetChartsQuery(teamId, ChartLevel.PROJECT, ChartSet.ELASTIC);

  return (
    <Grid container>
      <Grid item md={6} xs={12}>
        <Box p={3} pb={0}>
          <AnalyticTagDropdownField name="tagNames" teamId={teamId} />
        </Box>
      </Grid>
      <Grid item md={6} xs={12}></Grid>
      <Grid item md={6} xs={12}>
        <Box p={3}>
          <OverallProjectsChart />
        </Box>
      </Grid>
      <Grid item md={6} xs={12}>
        <Box p={3}>
          <RemainingFilesChart />
        </Box>
      </Grid>
      {config.app.featureToggle.enableAnalytics && (
        <Grid item xs={12}>
          <Box pt={4}>
            <AnalyticTrendsDateFilter />
          </Box>
        </Grid>
      )}
      {config.app.featureToggle.enableAnalytics && (
        <AnalyticChartsGrid
          chartsQuery={getChartsQuery}
          widgetProps={{ teamId, height: 334, hasTagFilter: true }}
        />
      )}
    </Grid>
  );
};

